<?php
require __DIR__.'/inc/v11.php';auth();v11_require();$id=(int)($_GET['id']??$_POST['id']??0);$q=$id?v11_quote($id):null;$err='';$ok='';$inventoryProtected=$q?ekQuoteProtectionReason(db(),$q):'';
function inventoryApplyPreview(array $quote,float $volume,int $pieces):array {
 $total=round(max(0,$volume*(float)$quote['unit_price']+(float)$quote['extra_price']-(float)$quote['discount']),2);
 $version=hash('sha256',json_encode([$quote['id'],$quote['volume'],$quote['pieces'],$quote['unit_price'],$quote['extra_price'],$quote['discount'],$quote['currency'],$quote['total'],$volume,$pieces],JSON_THROW_ON_ERROR));
 return ['total'=>$total,'version'=>$version];
}
if($_SERVER['REQUEST_METHOD']==='POST'){verify();if(!$q){$err='Teklif bulunamadı.';}else{try{db()->beginTransaction();$lockedInventoryQuote=ekLockQuote(db(),$id);ekAssertQuoteEditable(db(),$lockedInventoryQuote);$action=$_POST['action']??'';if($action==='add'){$room=mb_substr(trim($_POST['room']??''),0,100);$item=mb_substr(trim($_POST['item']??''),0,190);$qty=max(1,min(500,(int)($_POST['qty']??1)));$vol=max(0,min(1000,(float)($_POST['volume']??0)));if(!$room||!$item)throw new Exception('Oda ve eşya adı gerekli.');$s=db()->prepare('INSERT INTO v11_inventory(quote_id,room,item_name,quantity,unit_volume,notes) VALUES (?,?,?,?,?,?)');$s->execute([$id,$room,$item,$qty,$vol,mb_substr(trim($_POST['notes']??''),0,500)]);$ok='Eşya eklendi.';}elseif($action==='delete'){
  $rowId=(int)($_POST['row_id']??0);
  $s=db()->prepare('SELECT item_name,quantity FROM v11_inventory WHERE id=? AND quote_id=?');$s->execute([$rowId,$id]);$old=$s->fetch();
  if(!$old)throw new Exception('Silinecek eşya bulunamadı.');
  $s=db()->prepare('DELETE FROM v11_inventory WHERE id=? AND quote_id=?');$s->execute([$rowId,$id]);
  v11_event($id,'inventory_item_deleted',['item'=>$old['item_name'],'quantity'=>$old['quantity']]);
  $ok='Eşya envanterden kaldırıldı. Teklif hacmi otomatik değişmedi; gerekirse Hacmi Teklife Aktar butonunu kullanın.';
}elseif($action==='apply'){
  if(in_array(strtolower((string)$lockedInventoryQuote['status']),['accepted','approved','completed'],true))throw new RuntimeException('Onaylanmış teklifin hacmi doğrudan değiştirilemez.');
  $s=db()->prepare('SELECT COALESCE(SUM(quantity*unit_volume),0) AS volume,COALESCE(SUM(quantity),0) AS pieces FROM v11_inventory WHERE quote_id=?');
  $s->execute([$id]);$inventoryTotals=$s->fetch();
  $vol=round((float)$inventoryTotals['volume'],3);$pieces=(int)$inventoryTotals['pieces'];
  if($vol<=0)throw new RuntimeException('Aktarmadan önce pozitif hacimli eşya ekleyin.');
  $preview=inventoryApplyPreview($lockedInventoryQuote,$vol,$pieces);
  if($preview['total']>999999999)throw new RuntimeException('Teklif tutarı geçersiz.');
  $expected=$_POST['preview']??null;
  if(!is_string($expected)||!hash_equals($preview['version'],$expected))throw new RuntimeException('Teklif veya envanter değişti. Güncel tutarı kontrol edip yeniden aktarın.');
  if((float)$lockedInventoryQuote['volume']!==$vol||(float)$lockedInventoryQuote['total']!==$preview['total']||(int)$lockedInventoryQuote['pieces']!==$pieces){
   $s=db()->prepare('SELECT * FROM quote_details WHERE quote_id=?');$s->execute([$id]);
   ekSnapshotQuote(db(),$lockedInventoryQuote,$s->fetch()?:[],v11_meta($id),(int)$_SESSION['uid']);
   $s=db()->prepare('UPDATE quotes SET volume=?,pieces=?,total=? WHERE id=?');$s->execute([$vol,$pieces,$preview['total'],$id]);
   v11_event($id,'inventory_volume_applied',['volume'=>$vol,'previous_total'=>$lockedInventoryQuote['total'],'total'=>$preview['total']]);
  }
  $ok='Hacim teklife aktarıldı. '.number_format($vol,2,',','.').' m³';$q=v11_quote($id);
}db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}}
$picker=v11QuotePicker();$quotes=$picker['rows'];$rows=[];$total=0;if($q){$s=db()->prepare('SELECT * FROM v11_inventory WHERE quote_id=? ORDER BY room,id');$s->execute([$id]);$rows=$s->fetchAll();foreach($rows as $r)$total+=$r['quantity']*$r['unit_volume'];}
$applyPreview=$q?inventoryApplyPreview($q,round($total,3),array_sum(array_column($rows,'quantity'))):null;
require __DIR__.'/inc/layout.php';top('Eşya Envanteri');?><link rel="stylesheet" href="assets/v11.css?v=331301"><div class="v11-head"><h1>Oda Bazlı Eşya Envanteri</h1><p>Her teklifin envanteri ayrı saklanır. Toplam hacmi onaylayarak teklife aktarabilirsiniz.</p></div><?php v11QuotePickerNav($picker,$id);?><form method="get" class="v11-card"><label>Teklif seçin <input type="hidden" name="q" value="<?=h($picker['term'])?>"><input type="hidden" name="page" value="<?=$picker['page']?>"><select name="id" onchange="this.form.submit()"><option value="">Teklif seçiniz</option><?php if($q&&!in_array($id,array_map('intval',array_column($quotes,'id')),true)):?><option value="<?=$id?>" selected><?=h($q['quote_no'])?></option><?php endif;?><?php foreach($quotes as $a):?><option value="<?=$a['id']?>" <?=$id==$a['id']?'selected':''?>><?=h($a['quote_no'])?></option><?php endforeach;?></select></label></form><?php if($err):?><p class="error"><?=h($err)?></p><?php endif;if($ok):?><p class="notice"><?=h($ok)?></p><?php endif;if($q):?><?php if($inventoryProtected!==''):?><p class="notice"><?=h($inventoryProtected)?> <a href="quote.php?id=<?=$id?>">Yeni taslak revizyon</a></p><?php endif;?><fieldset <?=$inventoryProtected!==''?'disabled':''?> style="border:0;padding:0;margin:0;min-width:0"><div class="v11-card"><h2><?=h($q['quote_no'])?> · <?=h($q['name'])?></h2><p>Envanter hacmi: <strong><?=h(number_format($total,2,',','.'))?> m³</strong></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="apply"><input type="hidden" name="preview" value="<?=h($applyPreview['version'])?>"><?php if($total>0):?><p>Teklif tutarı <?=money($q['total'],$q['currency'])?> → <?=money($applyPreview['total'],$q['currency'])?></p><?php endif;?><button <?=$total<=0?'disabled':''?>>Hacmi Teklife Aktar</button></form></div><div class="v11-card"><h2>Eşya Ekle</h2><form method="post" class="v11-fields"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="add"><label>Oda<select name="room"><?php foreach(['Salon','Yatak Odası','Çocuk Odası','Mutfak','Banyo','Çalışma Odası','Antre','Depo','Diğer'] as $r):?><option><?=h($r)?></option><?php endforeach;?></select></label><label>Eşya adı<input name="item" required placeholder="Örn. Üçlü koltuk"></label><label>Adet<input type="number" min="1" max="500" name="qty" value="1" required></label><label>Birim hacim (m³)<input data-ek-volume type="number" step="0.001" min="0" name="volume" value="0.5" required></label><label>Not<input name="notes" maxlength="500"></label><button>Eşya Ekle</button></form></div><div class="v11-card"><h2>Envanter Listesi</h2><div class="v11-table"><table><thead><tr><th>Oda</th><th>Eşya</th><th>Adet</th><th>Birim m³</th><th>Toplam m³</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['room'])?></td><td><?=h($r['item_name'])?></td><td><?=h($r['quantity'])?></td><td><?=h(number_format((float)$r['unit_volume'],2,',','.'))?></td><td><?=h(number_format($r['quantity']*$r['unit_volume'],2,',','.'))?></td><td><form method="post" onsubmit="return confirm('Eşya silinsin mi?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="row_id" value="<?=$r['id']?>"><button class="v11-small" name="action" value="delete">Sil</button></form></td></tr><?php endforeach;?></tbody></table></div></div></fieldset><?php endif;bottom();
